-- =============================================================
-- Migration 058 — Sale by Channel history for the weekly report workbook
--
-- The Excel attachment on the weekly report email reproduces the stores'
-- workbooks sheet for sheet, and their "Sale by Channel" sheet runs weekly
-- from 29 Apr 2024. VM only holds GROSS per-channel sales from Mar 2026
-- (vm_sales_store_channel); the vm_yoy_* history is a different series and does
-- not match the figures the stores typed. So the typed history is imported
-- here, once, verbatim from the two workbooks (w/c 17 Aug 2026 copies).
--
-- VM wins for any week it holds — this table only fills the weeks it does not.
--
-- Corrected on import (day/month typed the wrong way round on the Hitchin
-- sheet, each obvious from its neighbours): 2026-02-03 -> 2026-03-02,
-- 2026-06-04 -> 2026-04-06, text '20/04/26' and '27/04/26' -> ISO dates.
--
-- Idempotent: the seed never overwrites a row that already exists.
-- =============================================================

create table if not exists public.weekly_report_channel_history (
  store_id         uuid not null references public.stores(id) on delete cascade,
  week_start       date not null,
  click_collect    numeric(12,2),
  deliveroo        numeric(12,2),
  just_eat         numeric(12,2),
  kiosk            numeric(12,2),
  own_delivery     numeric(12,2),
  uber_eats        numeric(12,2),
  till_eat_in      numeric(12,2),
  till_takeaway    numeric(12,2),
  -- As typed in the workbook's "Last year sales" column; null = none typed.
  last_year_sales  numeric(12,2),
  created_at       timestamptz not null default now(),
  primary key (store_id, week_start)
);

alter table public.weekly_report_channel_history enable row level security;

drop policy if exists "weekly_report_channel_history_select" on public.weekly_report_channel_history;
create policy "weekly_report_channel_history_select" on public.weekly_report_channel_history
  for select to authenticated
  using (public.is_staff());

